insert into role_templates (key, name, description, rank) values
  ('tenant_owner', 'Owner', 'The business owner. Full control of the tenant, including billing and transferring ownership.', 10),
  ('tenant_admin', 'Administrator', 'Full control of the business across every branch.', 20),
  ('branch_manager', 'Branch Manager', 'Runs one or more branches: staff, stock, pricing, refunds and reporting.', 30),
  ('inventory_manager', 'Inventory Manager', 'Manages stock, purchasing and suppliers. No access to sales revenue.', 40),
  ('accountant', 'Accountant', 'Reads financial data across branches. Cannot sell or change stock.', 40),
  ('supervisor', 'Supervisor', 'Runs a shift: approves refunds and discounts, handles the cash drawer.', 50),
  ('cashier', 'Cashier', 'Operates the till. Cannot refund, discount, or view cost prices.', 60),
  ('staff', 'Staff', 'Read-only access to the catalogue and stock levels.', 70)
